## 3. Program Structure Overview

```
AERIA SOLUTIONS LTD — INTEGRATED SAFETY & OPERATIONS PROGRAM v5.0

├── 00  GOVERNANCE                    Program structure, document control, org chart
├── 01  RPAS OPERATIONS               Policies, procedures, and guides for drone ops
