├── 05  CREW RESOURCE MANAGEMENT      CRM policy and human factors procedures
├── 06  HEALTH, SAFETY & ENVIRONMENT  HSE policies and procedures (SECOR aligned)
├── 07  LAND & MARINE OPERATIONS      Non-RPAS data acquisition procedures
├── 08  ADMINISTRATIVE                Records, privacy, retention policies
├── 09  FORMS & TEMPLATES             Field-ready forms and checklists
