## 3. Transport Canada — CARs Part IX

### 3.1 RPOC Requirements (CAR 901.214 - 901.221)

| Regulation | Requirement | Aeria Document(s) |
|:-----------|:------------|:------------------|
| **CAR 901.214(a)** | Applicant legal name, trade names | GOV-003 |
| **CAR 901.214(b)** | Addresses and contact information | GOV-003 |
| **CAR 901.214(c)** | Accountable Executive designation | GOV-003 |
| **CAR 901.214(d)** | Documentation established | GOV-001, GOV-002 |
| **CAR 901.215** | Operations Manager designation | GOV-003 |
| **CAR 901.216** | Person Responsible for Maintenance | GOV-003, MCM-001 |
| **CAR 901.217** | Operations Manual requirements | RPAS-001 to RPAS-010, procedures |
| **CAR 901.218(a)** | Safety goals and means to achieve | SMS-001 Section 5 |
| **CAR 901.218(b)** | Hazard identification processes | SMS-001 Section 6, HSE-003 |
| **CAR 901.218(c)** | Risk management processes | SMS-001 Section 6, SMS-002-PR |
| **CAR 901.218(d)** | Corrective action processes | SMS-001 Section 7, SMS-005-PR |
| **CAR 901.218(e)** | Record keeping processes | GOV-002, ADM-001-PR |
| **CAR 901.219** | Competence and training | TCP-001 |
| **CAR 901.221** | Maintenance Control Manual | MCM-001 |

### 3.2 Pilot Certification Requirements

| Regulation | Requirement | Aeria Document(s) |
|:-----------|:------------|:------------------|
| **CAR 901.56** | Basic operations qualifications | RPAS-002, TCP-001 |
| **CAR 901.63** | Recency requirements (24 months) | RPAS-002, RPAS-012-PR, TCP-003-PR |
| **CAR 901.65** | Advanced operations qualifications | RPAS-002, TCP-001 |
