  'Flight Operations',
  '# AERIA SOLUTIONS LTD

# INSPECTION OPERATIONS GUIDE

---

| Field | Value |
|:------|:------|
| **Document Number** | GUIDE-INSPECT |
| **Version** | v5.0 |
