| Natural Resources Canada - Explosives | natural-resources.canada.ca |
| WorkSafeBC - Blasting | worksafebc.com |
| Transport Canada - TDG | tc.canada.ca |
| CANUTEC Emergency | 1-888-226-8832 |

---

