| Guideline | Rationale |
|:----------|:----------|
| Maintain distance | Minimize stress response |
| Fly higher | Reduce noise impact |
| Avoid startling | Gradual approach if needed |
| Watch behavior | Signs of disturbance |
| Coordinate | Owner knows animals |

