| 3.2 | Weather exposure | Extended operations | Heat/cold stress | 3 | 3 | 9-M | Appropriate gear, rotation, monitoring | 4-L |
| 3.3 | Wildlife | Remote areas | Encounter | 2 | 3 | 6-L | Bear spray, awareness | 3-L |
